INSERT INTO `wp_postmeta` (`meta_id`,`post_id`,`meta_key`,`meta_value`) VALUES ('889','1','_wp_trash_meta_status','publish'),('890','1','_wp_trash_meta_time','1789434543'),('891','1','_wp_desired_post_slug','hello-world'),('892','1','_wp_trash_meta_comments_status','a:1:{i:1;s:1:\"1\";}'),('893','2','_wp_trash_meta_status','publish'),('894','2','_wp_trash_meta_time','1789434544'),('895','2','_wp_desired_post_slug','sample-page'),('896','152','rank_math_focus_keyword','cost of buying a property, property transfer tax'),('897','152','rank_math_title','The Costs That Come After the Asking Price | Estatein'),('898','152','rank_math_description','Transfer tax, legal fees, inspection, insurance. A rundown of what a purchase costs on top of the listing price, and which of them you can influence.'),('899','150','rank_math_focus_keyword','property valuation, how valuations are calculated'),('900','150','rank_math_title','How Property Valuations Are Actually Calculated | Estatein'),('901','150','rank_math_description','Valuation looks like an opinion and is mostly arithmetic. Here is what a surveyor is really doing when they put a number on a home.'),('902','148','rank_math_focus_keyword','property viewing checklist, viewing a property'),('903','148','rank_math_title','What to Check Before You View a Property | Estatein'),('904','148','rank_math_description','A viewing is short and easy to get wrong. These are the checks worth making before you arrive, and the questions worth asking while you are there.');

DROP TABLE IF EXISTS `wp_posts`;
CREATE TABLE `wp_posts` (
  `ID` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint(20) unsigned NOT NULL DEFAULT 0,
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_title` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_excerpt` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `post_password` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `post_name` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `to_ping` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `pinged` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_parent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `guid` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `menu_order` int(11) NOT NULL DEFAULT 0,
  `post_type` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `comment_count` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=156 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
INSERT INTO `wp_posts` (`ID`,`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_password`,`post_name`,`to_ping`,`pinged`,`post_modified`,`post_modified_gmt`,`post_content_filtered`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) VALUES ('1','1','2026-09-14 13:44:11','2026-09-14 13:44:11','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','trash','open','open','','hello-world__trashed','','','2026-09-15 09:09:03','2026-09-15 01:09:03','','0','http://localhost/estatein/?p=1','0','post','','1'),('2','1','2026-09-14 13:44:11','2026-09-14 13:44:11','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://localhost/estatein/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','trash','closed','open','','sample-page__trashed','','','2026-09-15 09:09:04','2026-09-15 01:09:04','','0','http://localhost/estatein/?page_id=2','0','page','','0'),('3','1','2026-09-14 13:44:11','2026-09-14 13:44:11','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost/estatein.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-09-14 13:44:11','2026-09-14 13:44:11','','0','http://localhost/estatein/?page_id=3','0','page','','0'),('4','0','2026-09-14 13:44:12','2026-09-14 13:44:12','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-09-14 13:44:12','2026-09-14 13:44:12','','0','http://localhost/estatein/index.php/2026/09/14/navigation/','0','wp_navigation','','0'),('5','0','2026-09-14 21:44:25','2026-09-14 13:44:25','','Home','','publish','closed','closed','','home','','','2026-09-14 21:44:25','2026-09-14 13:44:25','','0','http://localhost/estatein/home/','0','page','','0'),('6','0','2026-09-14 21:44:25','2026-09-14 13:44:25','','About Us','','publish','closed','closed','','about-us','','','2026-09-14 21:44:25','2026-09-14 13:44:25','','0','http://localhost/estatein/about-us/','0','page','','0'),('7','0','2026-09-14 21:44:25','2026-09-14 13:44:25','','Properties','','publish','closed','closed','','properties','','','2026-09-14 21:44:25','2026-09-14 13:44:25','','0','http://localhost/estatein/properties/','0','page','','0'),('8','0','2026-09-14 21:44:25','2026-09-14 13:44:25','','Services','','publish','closed','closed','','services','','','2026-09-14 21:44:25','2026-09-14 13:44:25','','0','http://localhost/estatein/services/','0','page','','0'),('9','0','2026-09-14 21:44:25','2026-09-14 13:44:25','','Contact Us','','publish','closed','closed','','contact-us','','','2026-09-14 21:44:25','2026-09-14 13:44:25','','0','http://localhost/estatein/contact-us/','0','page','','0'),('14','0','2026-09-14 21:54:40','2026-09-14 13:54:40','Wake up to the sound of the sea. This four-bedroom villa sits on a quiet coastal street, with floor-to-ceiling glazing across the living space and a private terrace that catches the afternoon sun.\n\nThe kitchen is fully fitted, the primary suite has a walk-in wardrobe and an ensuite, and there is off-street parking for two cars. The beach is a six-minute walk.','Seaside Serenity Villa','A stunning 4-bedroom, 3-bathroom villa in a peaceful suburban neighborhood, moments from the water.','publish','closed','closed','','seaside-serenity-villa','','','2026-09-15 09:09:00','2026-09-15 01:09:00','','0','http://localhost/estatein/property/seaside-serenity-villa/','1','property','','0'),('15','0','2026-09-14 21:54:40','2026-09-14 13:54:40','','property-1','','inherit','open','closed','','property-1','','','2026-09-14 21:54:40','2026-09-14 13:54:40','','0','http://localhost/estatein/property-1/','0','attachment','image/jpeg','0'),('16','0','2026-09-14 21:54:40','2026-09-14 13:54:40','A two-bedroom apartment on the twenty-second floor, sold fully furnished. Floor-to-ceiling windows run the length of the living room and both bedrooms, and the building has a residents\' gym, roof terrace and 24-hour concierge.\n\nTransport links are on the doorstep, with two underground lines and the business district within fifteen minutes.','Metropolitan Haven','A chic and fully-furnished 2-bedroom apartment with panoramic city views.','publish','closed','closed','','metropolitan-haven','','','2026-09-15 09:09:00','2026-09-15 01:09:00','','0','http://localhost/estatein/property/metropolitan-haven/','2','property','','0'),('17','0','2026-09-14 21:54:40','2026-09-14 13:54:40','','property-2','','inherit','open','closed','','property-2','','','2026-09-14 21:54:40','2026-09-14 13:54:40','','0','http://localhost/estatein/property-2/','0','attachment','image/jpeg','0'),('18','0','2026-09-14 21:54:40','2026-09-14 13:54:40','A three-bedroom townhouse in a gated development, arranged over three floors with a private garden to the rear. Original brickwork and exposed beams sit alongside a recently rebuilt kitchen and bathrooms.\n\nThe development has its own security gate, visitor parking and a shared green.','Rustic Retreat Cottage','An elegant 3-bedroom, 2.5-bathroom townhouse in a gated community.','p